Q: ViewTreeLifecycleOwner not found from Dialog A: <p><code>initializeViewTreeOwners()</code> is working!</p>
<pre class="lang-kotlin prettyprint-override"><code>class MyDialog(context: Context) : BottomSheetDialog(context){

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        initializeViewTreeOwners()
        setContentView(
            ComposeView(context).apply {
                setContent {
                    ComposeContent()
                }
            },
        )
    }
}
</code></pre>
